import sys, importlib.util, json
from pathlib import Path
sys.dont_write_bytecode = True
root = Path('/home/michael/code/kanken-training-2-decomp/scratch/worktrees/c010-def-sound')
sys.path.insert(0, str(root / 'tools'))
p = Path('/home/michael/code/kanken-training-2-decomp/scratch/worktrees/c010/scratch/integrator/c010/owner-cutover/factory_facts.py')
spec = importlib.util.spec_from_file_location('private_sound_facts', p)
f = importlib.util.module_from_spec(spec); spec.loader.exec_module(f)
f.image.ROOT = root
original = f.image.Image.load()
functions = f.image.functions_by_address(f.image.load_catalogue(root / 'config/catalogue.json'))

from collections import deque
def scoped_return_values(address):
    fn = functions[address]
    d = f.capstone.Cs(f.capstone.CS_ARCH_ARM, f.capstone.CS_MODE_THUMB if fn['isa']=='thumb' else f.capstone.CS_MODE_ARM)
    d.detail=True
    decoded = {ins.address:ins for start,stop in fn['code_ranges'] for ins in d.disasm(original.read(start,stop-start),start)}
    facts=f.argcheck.decode_function(original,fn,d)
    entries={entry['address'] for entry in fn['entries']}
    blocks,successors=f.argcheck.blocks(facts,sorted(entries))
    initial={f'r{i}':('parameter',address,f'r{i}') for i in range(4)}
    initial['sp']=('stack',address,0)
    incoming={i:initial.copy() for i,b in enumerate(blocks) if b[0].address in entries}
    queue=deque(incoming)
    while queue:
        i=queue.popleft(); state=incoming[i].copy()
        for fact in blocks[i]: f.flow.transfer(decoded[fact.address],fact,state,original,address,fn['code_ranges'])
        for j in successors[i]:
            prev=incoming.get(j)
            merged=state.copy() if prev is None else {k:v for k,v in prev.items() if state.get(k)==v}
            if prev!=merged: incoming[j]=merged; queue.append(j)
    results=[]
    for i,state in incoming.items():
        state=state.copy()
        for fact in blocks[i]:
            if fact.flow=='return':
                results.append({'offset':fact.address-address,'value':f.describe(state.get('r0'))})
            f.flow.transfer(decoded[fact.address],fact,state,original,address,fn['code_ranges'])
    return results


targets = [0x001d3c2c,0x0016a104,0x0018d728,0x001d65e0,0x001d6ab8,0x001d80b0,0x001d7f5c,0x001d81ec,0x001d9050,0x001d4324,0x001d4174,0x001d6094,0x001d773c,0x001d82b0,0x001d7b6c,0x001d48d4,0x0014b824,0x0014d690,0x001d3a08]
report={'schema_version':1,'image_sha256':original.sha256,'functions':[dict(f.inspect(original,functions[a]),size=functions[a]['size'],abstract_return_r0=scoped_return_values(a)) for a in targets], 'qualification':'Read-only scoped CFG and original field/call facts, not runtime execution or a whole-image argument audit. A live incoming register and a terminal r0 expression do not by themselves prove source arity or a meaningful result. Unknown merges remain unknown. No ROM bytes, instruction text, instruction encodings, or licensed payload are retained.'}
print(json.dumps(report))

